(function () {
  var base = window.VC_PRODUCT_FOR;
  var user = window.VC_PRODUCTS.filter(function (p) { return p.key === 'wiki'; })[0];
  var admin = window.VC_PRODUCTS.filter(function (p) { return p.key === 'wiki-admin'; })[0];
  var shared = {"spaces": 1, "oauth-applications": 1, "api-tokens": 1, "events": 1, "changelog": 1};
  function file(path) { return (path.split('/').pop() || '').replace(/\.html$/, ''); }
  function remembered() { try { return sessionStorage.getItem('wiki-guide'); } catch (e) { return null; } }
  window.VC_PRODUCT_FOR = function (path) {
    if (path.indexOf('/wiki/admin/') !== -1) return admin;
    if (path.indexOf('/wiki/') === -1) return base ? base(path) : null;
    if (shared[file(path)] && remembered() === 'admin') return admin;
    return user;
  };
  try {
    var here = location.pathname;
    if (here.indexOf('/wiki/admin/') !== -1) sessionStorage.setItem('wiki-guide', 'admin');
    else if (here.indexOf('/wiki/docs/') !== -1 && !shared[file(here)]) sessionStorage.setItem('wiki-guide', 'user');
  } catch (e) {}
})();
